themes.css:
.card-container {
  --secondary-background-color: #ece6f0;
  --primary-background-color: #f3edf7;
  --input-fill-color: #ece6f0;
  --mdc-select-fill-color: #ece6f0;
  --mdc-text-field-fill-color: #ece6f0;
  --mdc-theme-surface: #f7f2fa;
  background-color: #f7f2fa !important;
  background-image: none !important;
  border: none !important;
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.3), 0 1px 3px 1px rgba(0, 0, 0, 0.15) !important;
  /* MD3 body-medium tracking. */
  letter-spacing: 0.25px;
}
/* Nested surfaces read as surface-container-high. */
[style*="--uc-design-surface"] {
  background-color: #ece6f0;
  background-image: none;
  border: none;
  box-shadow: none;
}

.card-container {
  --secondary-background-color: #e4e8ef;
  --primary-background-color: #e4e8ef;
  --input-fill-color: #e4e8ef;
  --mdc-select-fill-color: #e4e8ef;
  --mdc-text-field-fill-color: #e4e8ef;
  --divider-color: transparent;
  background-color: #e4e8ef !important;
  /* A barely-there sheen toward the light so the slab reads as a solid, not a flat fill. */
  background-image: linear-gradient(145deg, #ffffff22 0%, #e4e8ef00 45%, #b8c2d31f 100%) !important;
  border: none !important;
  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.9), inset -1px -1px 0 rgba(0, 0, 0, 0.08), 10px 10px 22px #b8c2d3, -10px -10px 22px #ffffff !important;
}
/* Nested surfaces are the same material, recessed into the slab. */
[style*="--uc-design-surface"] {
  background-image: linear-gradient(#e4e8ef, #e4e8ef);
  border: none;
  box-shadow: inset 5px 5px 10px #b8c2d3, inset -5px -5px 10px #ffffff;
}
/* Hairlines vanish: neumorphism draws edges with light, not lines. */
.card-container hr,
.card-container [class*="divider"],
.card-container [class*="separator"] {
  border-color: transparent;
  background: transparent;
  box-shadow: 5px 5px 12px #b8c2d3, -5px -5px 12px #ffffff;
}

.card-container {
  --secondary-background-color: #2a2e35;
  --primary-background-color: #2a2e35;
  --input-fill-color: #2a2e35;
  --mdc-select-fill-color: #2a2e35;
  --mdc-text-field-fill-color: #2a2e35;
  --divider-color: transparent;
  background-color: #2a2e35 !important;
  /* A barely-there sheen toward the light so the slab reads as a solid, not a flat fill. */
  background-image: linear-gradient(145deg, #3c424c22 0%, #2a2e3500 45%, #1315191f 100%) !important;
  border: none !important;
  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.06), inset -1px -1px 0 rgba(0, 0, 0, 0.3), 10px 10px 22px #131519, -10px -10px 22px #3c424c !important;
}
/* Nested surfaces are the same material, recessed into the slab. */
[style*="--uc-design-surface"] {
  background-image: linear-gradient(#2a2e35, #2a2e35);
  border: none;
  box-shadow: inset 5px 5px 10px #131519, inset -5px -5px 10px #3c424c;
}
/* Hairlines vanish: neumorphism draws edges with light, not lines. */
.card-container hr,
.card-container [class*="divider"],
.card-container [class*="separator"] {
  border-color: transparent;
  background: transparent;
  box-shadow: 5px 5px 12px #131519, -5px -5px 12px #3c424c;
}

.card-container {
  position: relative;
  isolation: isolate;
  --secondary-background-color: rgba(255, 255, 255, 0.1);
  --primary-background-color: rgba(255, 255, 255, 0.06);
  --input-fill-color: rgba(255, 255, 255, 0.1);
  --mdc-select-fill-color: rgba(255, 255, 255, 0.1);
  --mdc-text-field-fill-color: rgba(255, 255, 255, 0.1);
  --rgb-card-background-color: 255, 255, 255;
  --rgb-primary-text-color: 16, 34, 77;
  color: #10224d;
  background-color: rgba(255, 255, 255, 0.08) !important;
  /* Specular top-left, a fainter lens light bottom-right, the rest clear. */
  background-image:
    radial-gradient(120% 70% at 8% 0%, rgba(255, 255, 255, 0.16) 0%, rgba(255, 255, 255, 0) 48%),
    radial-gradient(80% 50% at 96% 100%, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0) 55%) !important;
  /* See-through: a moderate blur keeps the wallpaper's shapes legible through the pane. */
  backdrop-filter: blur(var(--uc-blur, 10px)) saturate(150%);
  -webkit-backdrop-filter: blur(var(--uc-blur, 10px)) saturate(150%);
  border: none !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5), inset 0 -1px 0 rgba(255, 255, 255, 0.14), inset 0 0 18px rgba(255, 255, 255, 0.05), 0 14px 36px rgba(30, 60, 140, 0.22), 0 2px 6px rgba(30, 60, 140, 0.12) !important;
}
