/* The refraction rim: a 1.5px ring painted with the lensing gradient,
   masked to the border zone so it is an edge, not a fill. */
.card-container::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: inherit;
  padding: 1.5px;
  pointer-events: none;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.95) 0%, rgba(255, 255, 255, 0.35) 18%, rgba(255, 255, 255, 0.08) 42%, rgba(255, 255, 255, 0.06) 58%, rgba(255, 255, 255, 0.4) 84%, rgba(255, 255, 255, 0.85) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
}
/* Nested surfaces are smaller lenses of the same glass. */
[style*="--uc-design-surface"] {
  background-color: rgba(255, 255, 255, 0.1);
  background-image: radial-gradient(120% 80% at 10% 0%, rgba(255, 255, 255, 0.16) 0%, rgba(255, 255, 255, 0) 50%);
  border: none;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5), inset 1px 0 0 rgba(255, 255, 255, 0.18), inset 0 -1px 0 rgba(255, 255, 255, 0.1), 0 4px 12px rgba(30, 60, 140, 0.12);
  backdrop-filter: blur(6px) saturate(130%);
  -webkit-backdrop-filter: blur(6px) saturate(130%);
}
/* Hairlines are ink at low opacity, never solid. */
.card-container hr,
.card-container [class*="divider"],
.card-container [class*="separator"] {
  border-color: rgba(16, 34, 77, 0.12);
  background-color: rgba(16, 34, 77, 0.12);
}

.card-container {
  /* A faint antler highlight on the top edge over a warm hide gradient. */
  background-image: linear-gradient(180deg, rgba(232, 217, 195, 0.05) 0%, rgba(232, 217, 195, 0) 40%) !important;
  box-shadow:
    inset 0 1px 0 rgba(232, 217, 195, 0.1),
    0 10px 28px rgba(12, 7, 3, 0.45),
    0 1px 2px rgba(12, 7, 3, 0.3) !important;
}

.card-container {
  /* The plate. */
  background-color: #d5d8db !important;
  background-image: repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.16) 0 1px, rgba(255, 255, 255, 0) 1px 3px, rgba(0, 0, 0, 0.035) 3px 4px), linear-gradient(180deg, #e4e7ea 0%, #d3d6d9 40%, #cbcfd3 100%) !important;
  border: 1px solid #a4aab0 !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 0 rgba(0, 0, 0, 0.18), 0 10px 24px rgba(0, 0, 0, 0.26), 0 1px 2px rgba(0, 0, 0, 0.28) !important;
  /* Engraved type: a hairline of light under each glyph. */
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.65);
  letter-spacing: 0.02em;
  /* Bar value text sits on the dark well and the lit fill, so it stays white here. */
  --uc-bar-text: #ffffff;
  --uc-bar-text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
}
/* Every metallic control is spun aluminium with dark type. Only the metallic
   recipe is touched, so a control a user has switched to another style keeps it. */
[data-uc-surface="metallic"][data-uc-role="control"] {
  background: radial-gradient(circle at 50% 30%, rgba(255, 255, 255, 0.55) 0%, rgba(255, 255, 255, 0) 60%), conic-gradient(from 20deg, #dfe3e6, #aab0b6 12%, #eef0f2 24%, #b3b9be 38%, #e9ecee 50%, #a9afb5 63%, #eaedf0 76%, #b6bcc1 88%, #dfe3e6) !important;
  border: 1px solid #8e959c !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), inset 0 -1px 0 rgba(0, 0, 0, 0.28), 0 2px 3px rgba(0, 0, 0, 0.35), 0 6px 10px rgba(0, 0, 0, 0.14) !important;
  color: #2a2e33 !important;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.7);
}
/* Tracks are sunk into the plate: a near-black well with a white lip below it.
   The bar's white value text reads on the well and on the lit fill alike. */
[data-uc-surface="metallic"][data-uc-role="track"] {
  background: linear-gradient(180deg, #202428, #2a2e32 40%, #383d42) !important;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.7), inset 0 1px 1px rgba(0, 0, 0, 0.6), 0 1px 0 rgba(255, 255, 255, 0.95) !important;
}

.card-container {
  /* This card's stretch of beach, from its seeds. */
  --b-s1: var(--uc-card-seed-1, 0.5);
  --b-s2: var(--uc-card-seed-2, 0.5);
  --b-s3: var(--uc-card-seed-3, 0.5);
  --b-tide: calc(16px + var(--b-s3) * 12px);
